import{_ as s,o as a,c as i,a2 as t}from"./chunks/framework.CWWEQfK7.js";const u=JSON.parse('{"title":"Start Ershu and reach the sign-in page","description":"Prepare the local Ershu services and confirm that the web interface can reach the API.","frontmatter":{"page_id":"guide-quick-start","description":"Prepare the local Ershu services and confirm that the web interface can reach the API."},"headers":[],"relativePath":"en/guide/quick-start.md","filePath":"en/guide/quick-start.md","lastUpdated":1786289447000}'),n={name:"en/guide/quick-start.md"};function r(p,e,h,l,o,d){return a(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="start-ershu-and-reach-the-sign-in-page" tabindex="-1">Start Ershu and reach the sign-in page <a class="header-anchor" href="#start-ershu-and-reach-the-sign-in-page" aria-label="Permalink to &quot;Start Ershu and reach the sign-in page&quot;">​</a></h1><p>This page is for maintainers who already have access to the internal component sources. The goal is to start the infrastructure, API, Worker, and frontend so that you can continue in the web interface.</p><div class="warning custom-block"><p class="custom-block-title">Public package installation is not available yet</p><p>The bundle and backend modules still obtain Core and other dependencies from private development sources. Without the required Git and SSH access, <code>uv sync --all-extras --frozen</code> fails while fetching those dependencies. There is currently no verified public installation command to use instead.</p></div><p>The commands below come from the current repository manifests and READMEs. They describe the intended procedure; they do not claim to have succeeded on your machine.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><p>Before starting, make sure you have:</p><ul><li>Python 3.14;</li><li>UV;</li><li>Docker and Docker Compose;</li><li>Node.js 24;</li><li>access to the current private component sources; and</li><li>a separate checkout of the matching <code>frontend</code> repository.</li></ul><p>Core is a shared package and does not run as a separate process. The first web analysis requires the PostgreSQL and Milvus infrastructure, the API, the Worker, and the frontend. Start MCP and the repository poller only when you need those features.</p><h2 id="step-1-start-the-infrastructure" tabindex="-1">Step 1: Start the infrastructure <a class="header-anchor" href="#step-1-start-the-infrastructure" aria-label="Permalink to &quot;Step 1: Start the infrastructure&quot;">​</a></h2><p>In the <code>ershu</code> bundle repository, copy the Compose settings:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.compose.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.compose</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Open <code>.env.compose</code>, replace the example PostgreSQL and MinIO passwords, and start the services:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ps</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>The <code>ps</code> output should show PostgreSQL, Redis, Milvus, etcd, and MinIO running. If a service repeatedly restarts, inspect that container before attempting a database migration.</p><h2 id="step-2-prepare-backend-settings" tabindex="-1">Step 2: Prepare backend settings <a class="header-anchor" href="#step-2-prepare-backend-settings" aria-label="Permalink to &quot;Step 2: Prepare backend settings&quot;">​</a></h2><p>Copy the current settings template:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Replace the example passwords and keys as directed by the comments. Confirm that the database, Redis, and Milvus addresses point to the services from the previous step. Do not put model names, model API keys, or model endpoints in <code>.env</code>; those belong to model channels in the web administration area.</p><p>At the end of this step, you should have a local-only <code>.env</code> without example secrets that might accidentally reach a real environment.</p><h2 id="step-3-install-the-backend-and-run-migrations" tabindex="-1">Step 3: Install the backend and run migrations <a class="header-anchor" href="#step-3-install-the-backend-and-run-migrations" aria-label="Permalink to &quot;Step 3: Install the backend and run migrations&quot;">​</a></h2><p>Run these commands only if your account can access the private component sources:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --all-extras</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --frozen</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ershu-db</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> head</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Both commands should finish with exit code <code>0</code>. If the first command cannot fetch Core or another Ershu package, you have reached the current public-installation limitation. Do not work around it by deleting the lockfile or substituting an unverified package.</p><h2 id="step-4-start-the-api-and-worker" tabindex="-1">Step 4: Start the API and Worker <a class="header-anchor" href="#step-4-start-the-api-and-worker" aria-label="Permalink to &quot;Step 4: Start the API and Worker&quot;">​</a></h2><p>Open two terminals and leave both processes running.</p><p>Terminal A:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ershu-api</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Terminal B:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ershu-worker</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Open <code>http://127.0.0.1:8000/health</code>. A live API returns a response whose status is <code>ok</code>. This endpoint only confirms that the API process is alive. <code>/api/v1/health/dependencies</code> also checks the database and Milvus, but it does not check Redis.</p><p>The Worker does not currently expose a browser health endpoint. Its process should remain running instead of exiting immediately. The final proof is that the first queued run advances through its analysis stages.</p><p>Start MCP in another terminal if you need it:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ershu-mcp</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Start the repository poller separately if you want scheduled repository checks:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ershu-api-poller</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Neither process is required for the first analysis through the web interface.</p><h2 id="step-5-start-the-frontend" tabindex="-1">Step 5: Start the frontend <a class="header-anchor" href="#step-5-start-the-frontend" aria-label="Permalink to &quot;Step 5: Start the frontend&quot;">​</a></h2><p>In the separate <code>frontend</code> repository, run:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.local</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>The development server uses <code>http://localhost:3000</code> by default and proxies <code>/api</code> to <code>http://localhost:8000</code>. If the API runs elsewhere, change <code>VITE_DEV_API_PROXY</code> in <code>.env.local</code> and restart the development server.</p><p>Open <code>http://localhost:3000</code>:</p><ul><li>a new database redirects you to initial administrator setup;</li><li>a database that already contains users redirects you to sign-in; and</li><li>repeated network errors mean that the frontend still cannot reach the API.</li></ul><p>You are now ready to <a href="./create-first-project">create your first project</a>.</p>`,43)])])}const k=s(n,[["render",r]]);export{u as __pageData,k as default};
